const rawInput = (items && items[0] && items[0].json) ? items[0].json : {};
const input = (rawInput && rawInput.body && typeof rawInput.body === "object") ? rawInput.body : rawInput;
const env = (typeof $env === "object" && $env !== null) ? $env : {};
const deepseekBaseUrl = String((env.DEEPSEEK_BASE_URL || "https://api.deepseek.com")).replace(/\/+$/, "");
const model = String(input.model || env.DEEPSEEK_MODEL || "deepseek-flash").trim() || "deepseek-flash";
const visionModel = String(input.visionModel || model).trim() || model;
const hints = {
  system: input.system === "TOUHOU" ? "TOUHOU" : "COC7",
  era: String(input.era || "MODERN"),
  instructions: String(input.instructions || "")
};
const sources = Array.isArray(input.sources) && input.sources.length > 0
  ? input.sources
  : (Array.isArray(input.chunks) ? input.chunks.map((chunk) => ({ filename: chunk.filename, text: chunk.text })) : []);
const images = Array.isArray(input.images) ? input.images : [];
const requests = [];

function structuredSchemaHint() {
  return [
    "structured 可用字段（只输出本段中出现的，没有就省略）。注意：下面的值只是字段格式示例，禁止把示例值当成素材内容照抄；未知字段一律省略。",
    '{"chapters":[{"id":"ch1","name":"章节名","summary":"..."}],',
    '"scenes":[{"id":"scene1","name":"场景名","description":"...","width":1600,"height":1000,"gridType":"SQUARE 或 HEX","bgColor":"#1a1a2e","background":"assets/images/xxx.png 或留空"}],',
    '"encounters":[{"id":"enc1","name":"遭遇名","sceneId":"scene1","sceneName":"场景名","chapterId":"ch1","chapterName":"章节名","trigger":"...","setup":{}}],',
    '"npcs":[{"id":"npc1","name":"NPC 名","tier":"MINION 或 STANDARD 或 ELITE 或 BOSS","rarity":"COMMON","race":null,"tags":[],"description":"...","portrait":"assets/images/xxx.png 或留空","statText":"原文中的属性行 / 数值块，逐字复制，例如 STR 50 CON 60 SIZ 65 DEX 70 APP 55 INT 80 POW 70 EDU 75 HP 12 MP 14 SAN 70\nDB 1d4 Build 1 Move 8","attributes":{"str":50,"con":50,"siz":50,"dex":50,"app":50,"int":50,"pow":50,"edu":50,"luck":50},"db":"1d4","build":1,"move":8,"skills":[{"skill_name":"DODGE","value":40}],"weapons":[{"weapon_name":"棍棒","damage":"1d6","range":"MELEE"}],"maxHp":12,"maxMp":10,"maxSan":50,"maxDp":0}],',
    '"clues":[{"id":"clue1","title":"线索名","content":"线索正文","image":"assets/clues/xxx.png 或留空","isPublic":false,"linkedItemId":"item1 或留空","discoveryMethod":"侦察 / 图书馆使用 / 对话等","relatedNpc":"关联 NPC 名或留空","relatedPc":"发现线索的调查员或留空"}],',
    '"items":[{"id":"item1","name":"道具名","itemType":"WEAPON 或 ITEM 或 TOME 或 ARTIFACT 或 EVIDENCE","description":"...","rarity":"COMMON","image":"assets/images/xxx.png 或留空","quantity":1,"damage":"1d6 或留空","range":"MELEE 或 NEAR 或 FAR 或留空","skillId":"FIGHTING_BRAWL 等或留空","accuracyMod":0}],',
    '"endings":[{"id":"end1","name":"结局名","condition":"...","description":"..."}],',
    '"rewards":[{"id":"reward1","name":"奖励名","description":"..."}],',
    '"magic":[{"id":"spell1","name":"法术名","skill":"MAGIC 或 OCCULT","mpCost":"3","sanCost":"1d3","damage":"1d6","target":"ONE","targeting":"ENEMY","effects":[{"type":"DAMAGE","amount":"1d6"}],"description":"..."}]}'
  ].join("\n");
}

function chunkExtractionPrompt(chunk) {
  const lines = [];
  lines.push("请从下面这一小段团本素材中做“分块提取”。只处理这一段，不要参考其他段落或历史任务。");
  lines.push("目标系统：" + hints.system + "；年代：" + hints.era + "。");
  if (hints.instructions.trim().length > 0) lines.push("用户额外要求：" + hints.instructions.trim().slice(0, 2000));
  lines.push("来源：" + chunk.filename + "，本文件第 " + String(chunk.fileIndex) + "/" + String(chunk.fileTotal) + " 段" + (chunk.heading.length === 0 ? "" : "，最近标题：" + chunk.heading));
  lines.push("要求：");
  lines.push("- 只提取本段明确出现的事实、剧情、NPC、场景、线索、道具、法术；没有的字段直接省略，不要编造，也不要输出其他段落的内容。");
  lines.push("- 本段已按场景 / 章节 / 时间戳重新切分，请把它当作一个相对独立的场景来处理。若本段出现场景标题或明确地点，请在 structured.scenes 输出 1 条 scene，并将本场景关联的 npcs / clues / encounters / items / magic 一并输出，不要只写正文摘要。");
  lines.push("- NPC 数值优先级最高：原文有的 STR/CON/SIZ/DEX/APP/INT/POW/EDU/LUCK、HP/MP/SAN/DP、DB/Build/Move、技能、武器都必须提取；技能输出为 [{skill_name,value}]，武器输出为 [{weapon_name,damage,range}]。");
  lines.push("- 如果本段出现大量乱码、替换字符或明显编码损坏，不要猜测原文内容；meta.title 填来源文件名，sections 只写一条「本段原文不可读，未生成结构化数据」说明，structured 留空。");
  lines.push("- JSON 示例里的 50、1d6、场景名、NPC 名等都只是格式示例，不是素材内容；任何字段没有在原文中明确出现就不要输出，禁止用默认值 / 猜测值补全。");
  lines.push("- NPC 的属性、技能、HP / MP / SAN 等数值只有原文明确给出时才输出对应字段；原文没写就省略，系统会按规则包处理，不要自行编数值。");
  lines.push("- NPC 如果原文有属性行 / 数值块（STR 50、力量 60、HP 12、MP 14、SAN 70 等），必须把该行原样放进 statText，同时尽量拆进 attributes / maxHp / maxMp / maxSan；数字必须与原文完全一致。");
  lines.push("- 原文中的标题、编号 / 标记、专有名词、NPC / 场景 / 道具 / 技能 / 法术名、数字与判定值必须原样保留；压缩时只能压缩形容词，不能删除任何条目。");
  lines.push("- 叙事 / 设定按语义归入 sections 中最贴切的标准章节；实在无法归类就放入 附录。只要本段有正文，就至少输出一个 sections 字段，并尽量保留所有小节标题。");
  lines.push("- 结构化实体放入 structured；字段 id 用 slug，同一实体在不同段落请用同名 / 同 id，方便合并。");
  lines.push("- 输出必须是单个合法 JSON 对象，不要 markdown 代码围栏，不要解释。");
  lines.push("- 总长度控制在 4000 个中文字符以内，JSON 必须完整闭合。");
  lines.push("JSON 结构：");
  lines.push('{"meta":{"title":"...","summary":"...","background":"...","occupationRecommendation":"..."},');
  lines.push('"sections":{"元信息":"...","真相与背景":"...","剧情梗概":"...","开场钩子":"...","关键NPC":"...","地点与场景":"...","线索":"...","遭遇与战斗":"...","道具与手书":"...","怪物与神话生物":"...","结局分支":"...","奖励与成长":"...","KP备注":"...","附录":"..."},');
  lines.push('"structured":{...}}');
  lines.push(structuredSchemaHint());
  lines.push("");
  lines.push("本段原文：");
  lines.push(String(chunk.text || ""));
  return lines.join("\n");
}

function imageAnalysisPrompt(batch) {
  const lines = [];
  lines.push("请逐张分析下面的图片素材，并把结果整理成 JSON。");
  lines.push("目标系统：" + hints.system + "；年代：" + hints.era + "。");
  lines.push("要求：");
  lines.push("- 每张图片必须返回一条 images 记录，filename 与输入完全一致。");
  lines.push("- kind 只能是 MAP / SCENE / HANDOUT / CLUE / NPC / ITEM / TEXT / OTHER 之一。");
  lines.push("- transcription：逐字抄录图中可见文字（保留原文，可附中文翻译）；最多 2000 字。");
  lines.push("- description：客观描述画面内容、人物、地图结构、房间 / 地点标记，不要脑补素材中不存在的设定。");
  lines.push("- section：选一个最贴切的标准章节；sectionText：可直接写进该章节的中文正文（最多 1200 字）。");
  lines.push("- 如果图片是地图，尽量给出 scene（name / description / width / height / gridType）；是手书 / 文件就给 clue；是人物立绘就给 npc；是物品就给 item；否则对应字段返回 null。");
  lines.push("- 只返回单个合法 JSON 对象，不要解释、不要 markdown 代码围栏。");
  lines.push('JSON 结构：{"images":[{"filename":"...","kind":"MAP","transcription":"...","description":"...","section":"地点与场景","sectionText":"...","scene":{"id":"scene1","name":"...","description":"...","width":1600,"height":1000,"gridType":"SQUARE"},"clue":null,"npc":null,"item":null}]}');
  lines.push("");
  lines.push("图片清单：");
  for (const image of batch) {
    lines.push("- filename：" + image.filename + "；引用路径：" + image.relativePath);
    if (image.pageNumber !== undefined && image.pageNumber !== null) {
      lines.push("  来源：PDF 第 " + String(image.pageNumber) + " 页" + (image.origin === "PAGE_RENDER" ? "（整页渲染）" : "（内嵌图）"));
    }
    if (image.pageText !== undefined && String(image.pageText).trim().length > 0) {
      lines.push("  同页文字（可能不完整）：" + String(image.pageText).trim().slice(0, 1200));
    }
  }
  return lines.join("\n");
}

function isSceneBoundary(text) {
  const firstLine = String(text || "").split("\n")[0].trim();
  if (firstLine.length === 0) return false;
  if (/^(#{1,6}\s*)?(场景|第\s*[一二三四五六七八九十百0-9]+\s*[幕章节]|chapter|act\b)/i.test(firstLine)) return true;
  if (/^[-=—]{3,}$/.test(firstLine)) return true;
  if (/^\[\d{1,2}:\d{2}(?::\d{2})?\]/.test(firstLine)) return true;
  if (/^【[^】]*(场景|第\s*[一二三四五六七八九十百0-9]+\s*[幕章节])[^】]*】/.test(firstLine)) return true;
  return false;
}

function chunkSourceByScene(filename, rawText) {
  const target = 6000;
  const max = 9000;
  const normalized = String(rawText || "").replace(/\r\n?/g, "\n").trim();
  if (normalized.length === 0) return [];

  const paragraphs = [];
  let heading = "";
  for (const block of normalized.split(/\n{2,}/)) {
    const text = block.trim();
    if (text.length === 0) continue;
    const firstLine = text.split("\n")[0].trim();
    if (/^(#{1,6}\s+|【[^】]{1,40}】\s*$)/.test(firstLine)) {
      heading = firstLine.replace(/^#{1,6}\s+/, "").replace(/^【|】$/g, "").trim() || heading;
    }
    paragraphs.push({ text, heading });
  }
  if (paragraphs.length === 0) paragraphs.push({ text: normalized, heading });

  const expanded = [];
  for (const paragraph of paragraphs) {
    if (paragraph.text.length <= max) {
      expanded.push(paragraph);
      continue;
    }
    const pieces = paragraph.text.split(/(?<=[。！？!?；;])\s*/).filter((piece) => piece.trim().length > 0);
    let buffer = "";
    const flush = () => {
      if (buffer.trim().length > 0) expanded.push({ text: buffer.trim(), heading: paragraph.heading });
      buffer = "";
    };
    for (const piece of pieces) {
      if (piece.length > max) {
        flush();
        for (let offset = 0; offset < piece.length; offset += target) {
          expanded.push({ text: piece.slice(offset, offset + target), heading: paragraph.heading });
        }
        continue;
      }
      if (buffer.length + piece.length > target) flush();
      buffer += piece;
    }
    flush();
  }

  const output = [];
  let buffer = "";
  let bufferHeading = expanded[0] ? expanded[0].heading : "";
  let forceHeading = "";
  const pushChunk = () => {
    const text = buffer.trim();
    if (text.length === 0) return;
    output.push({ text, heading: forceHeading || bufferHeading, charCount: text.length });
    buffer = "";
  };

  for (const paragraph of expanded) {
    const startsScene = isSceneBoundary(paragraph.text);
    if (buffer.length > 0 && startsScene) pushChunk();
    if (buffer.length === 0) {
      bufferHeading = paragraph.heading;
      forceHeading = paragraph.heading;
    } else if (paragraph.heading.length > 0 && paragraph.heading !== bufferHeading) {
      if (buffer.length >= 1000) {
        pushChunk();
      }
      forceHeading = paragraph.heading;
    }
    if (buffer.length > 0 && buffer.length + paragraph.text.length + 2 > target) pushChunk();
    if (buffer.length > 0) buffer += "\n\n";
    buffer += paragraph.text;
    if (buffer.length >= target) pushChunk();
  }
  pushChunk();

  return output.map((chunk, index) => ({
    filename,
    fileIndex: index + 1,
    fileTotal: output.length,
    heading: chunk.heading,
    text: chunk.text,
    charCount: chunk.charCount
  }));
}

for (const source of sources) {
  const filename = String(source && source.filename ? source.filename : "material");
  const sceneChunks = chunkSourceByScene(filename, source ? source.text : "");
  for (const chunk of sceneChunks) {
    const label = "场景段 " + chunk.filename + " " + String(chunk.fileIndex) + "/" + String(chunk.fileTotal);
    requests.push({
      json: {
        kind: "chunk",
        label,
        chunk,
        url: deepseekBaseUrl + "/chat/completions",
        body: {
          model,
          temperature: 0.15,
          max_tokens: 8192,
          stream: false,
          response_format: { type: "json_object" },
          messages: [
            { role: "system", content: "你是严谨的中文 TRPG 团本编辑。当前任务是按场景分块提取素材，每次调用都是完全独立的导入任务，不继承任何历史上下文；只依据本次用户消息中的素材片段输出严格 JSON，不要续写、不要解释。" },
            { role: "user", content: chunkExtractionPrompt(chunk) }
          ]
        }
      }
    });
  }
}

const batchSize = 2;
for (let offset = 0; offset < images.length; offset += batchSize) {
  const batch = images.slice(offset, offset + batchSize);
  const content = [{ type: "text", text: imageAnalysisPrompt(batch) }];
  for (const image of batch) content.push({ type: "image_url", image_url: { url: image.dataUrl } });
  const label = "图片分析 " + batch.map((image) => image.filename).join("、").slice(0, 80);
  requests.push({
    json: {
      kind: "image",
      label,
      imageBatch: batch.map((image) => ({ filename: image.filename, relativePath: image.relativePath })),
      url: deepseekBaseUrl + "/chat/completions",
      body: {
        model: visionModel,
        temperature: 0.1,
        max_tokens: 8192,
        stream: false,
        response_format: { type: "json_object" },
        messages: [
          { role: "system", content: "你是 TRPG 素材视觉分析助手。每次调用都是独立任务，只依据当前图片与随图文字输出严格 JSON；看不清或不确定的内容必须如实说明，不得脑补。" },
          { role: "user", content }
        ]
      }
    }
  });
}

return requests;

/**
 * n8n 「团本解析」工作流：解析 HTTP Request 返回的 DeepSeek JSON，并用确定性规则回填 NPC 数值。
 *
 * 这个节点运行在 runOnceForAllItems 模式，输入是 HTTP Request 节点的所有响应。
 * 工作流前置节点会先发 chunk 请求，再发 image 请求，顺序固定，因此这里按顺序还原。
 */

"use strict";

/**
 * 确定性 NPC 数值解析核心。
 *
 * 这个文件会被 scripts/build-n8n-workflows.mjs 内联进 n8n Code 节点。
 * 也可以在离线测试里直接 require，重点覆盖：
 * - 英文缩写 / 中文属性名 / 分隔符 / 全角数字
 * - 同一行、逗号分隔、表格标签行 + 数值行
 * - 3d6 这类骰点不会被误读为 3
 * - 按 NPC 名字附近窗口回填，避免串读相邻 NPC
 * - 额外从原文中直接收割带名字的数值块（AI 漏掉的 NPC 也能补回来）
 */

const NPC_STAT_ATTRIBUTE_KEYS = ["str", "con", "siz", "dex", "app", "int", "pow", "edu", "luck"];

const ATTRIBUTE_GROUPS = [
  { key: "str", aliases: ["strength", "str", "力量"] },
  { key: "con", aliases: ["constitution", "con", "体质"] },
  { key: "siz", aliases: ["size", "siz", "体型"] },
  { key: "dex", aliases: ["dexterity", "dex", "敏捷"] },
  { key: "app", aliases: ["appearance", "app", "外貌", "魅力"] },
  { key: "int", aliases: ["intelligence", "int", "智力"] },
  { key: "pow", aliases: ["power", "pow", "意志", "意志力"] },
  { key: "edu", aliases: ["education", "edu", "教育"] },
  { key: "luck", aliases: ["luck", "幸运"] }
];

const VITAL_GROUPS = [
  { key: "hp", aliases: ["hit points", "hit point", "hp", "生命值", "生命", "耐久值", "耐久力", "耐久", "体力", "血量"] },
  { key: "mp", aliases: ["magic points", "magic point", "mp", "魔法值", "魔法点", "魔法", "魔力", "mp值"] },
  { key: "san", aliases: ["san值", "san", "理智值", "理智"] },
  { key: "dp", aliases: ["dp值", "dp"] }
];

const SEPARATORS = "[ \\t:：=,，;；|/()（）为是值可有达到]{0,12}";
const NUMBER_PATTERN = "(\\d{1,4})(?![0-9dD])";
const SIGNED_NUMBER_PATTERN = "([+-]?\\d{1,5})(?![0-9dD])";
const ALL_GROUPS = [...ATTRIBUTE_GROUPS, ...VITAL_GROUPS];

function escapeRegExp(value) {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function normalizeText(value) {
  return String(value || "")
    .replace(/[\uFF10-\uFF19]/g, (char) => String.fromCharCode(char.charCodeAt(0) - 0xfee0))
    .replace(/：/g, ":")
    .replace(/＝/g, "=");
}

function normalizeNameKey(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[\s_\-—–·•.。:：,，、;；!！?？'"“”‘’（）()【】\[\]《》<>\/\\]+/g, "")
    .slice(0, 120);
}

function groupValue(groups, alias) {
  const key = String(alias || "").trim().toLowerCase();
  for (const group of groups) {
    if (group.aliases.some((item) => item.toLowerCase() === key)) return group.key;
  }
  return undefined;
}

function collectDirectMatches(text, groups, signed) {
  const output = new Map();
  const aliases = groups.flatMap((group) => group.aliases);
  const english = aliases.filter((alias) => /^[a-z0-9 ]+$/i.test(alias)).sort((a, b) => b.length - a.length);
  const chinese = aliases.filter((alias) => /^[a-z0-9 ]+$/i.test(alias) === false).sort((a, b) => b.length - a.length);
  const numberPattern = signed ? SIGNED_NUMBER_PATTERN : NUMBER_PATTERN;

  if (english.length > 0) {
    const pattern = new RegExp(
      "\\b(" + english.map(escapeRegExp).join("|") + ")\\b" + SEPARATORS + numberPattern,
      "gi"
    );
    for (const match of text.matchAll(pattern)) {
      const key = groupValue(groups, match[1] || "");
      if (key === undefined || output.has(key)) continue;
      const value = Number(match[2]);
      if (Number.isFinite(value)) output.set(key, value);
    }
  }

  if (chinese.length > 0) {
    const pattern = new RegExp("(" + chinese.map(escapeRegExp).join("|") + ")" + SEPARATORS + numberPattern, "g");
    for (const match of text.matchAll(pattern)) {
      const key = groupValue(groups, match[1] || "");
      if (key === undefined || output.has(key)) continue;
      const value = Number(match[2]);
      if (Number.isFinite(value)) output.set(key, value);
    }
  }

  return output;
}

function containsValueAfterLabel(line, groups) {
  const aliases = groups.flatMap((group) => group.aliases).sort((a, b) => b.length - a.length);
  if (aliases.length === 0) return false;
  const english = aliases.filter((alias) => /^[a-z0-9 ]+$/i.test(alias));
  const chinese = aliases.filter((alias) => /^[a-z0-9 ]+$/i.test(alias) === false);
  const patterns = [];
  if (english.length > 0) patterns.push(new RegExp("\\b(?:" + english.map(escapeRegExp).join("|") + ")\\b" + SEPARATORS + NUMBER_PATTERN, "i"));
  if (chinese.length > 0) patterns.push(new RegExp("(?:" + chinese.map(escapeRegExp).join("|") + ")" + SEPARATORS + NUMBER_PATTERN));
  return patterns.some((pattern) => pattern.test(line));
}

function labelsInOrder(line, groups) {
  const aliases = groups.flatMap((group) => group.aliases).sort((a, b) => b.length - a.length);
  const english = aliases.filter((alias) => /^[a-z0-9 ]+$/i.test(alias));
  const chinese = aliases.filter((alias) => /^[a-z0-9 ]+$/i.test(alias) === false);
  const patternParts = [];
  if (english.length > 0) patternParts.push("\\b(?:" + english.map(escapeRegExp).join("|") + ")\\b");
  if (chinese.length > 0) patternParts.push("(?:" + chinese.map(escapeRegExp).join("|") + ")");
  if (patternParts.length === 0) return [];
  const pattern = new RegExp(patternParts.join("|"), "gi");
  return Array.from(line.matchAll(pattern)).map((match) => groupValue(groups, match[0]) || "").filter((key) => key.length > 0);
}

function extractAlignedPairs(text) {
  const output = new Map();
  const lines = String(text || "").split("\n").map((line) => line.trim()).filter((line) => line.length > 0);
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index] || "";
    if (line.length > 240 || containsValueAfterLabel(line, ALL_GROUPS)) continue;
    const keys = labelsInOrder(line, ALL_GROUPS);
    if (keys.length < 1) continue;
    for (let offset = 1; offset <= 2; offset += 1) {
      const next = lines[index + offset];
      if (next === undefined) break;
      const numbers = Array.from(next.matchAll(new RegExp(NUMBER_PATTERN, "g")))
        .map((match) => Number(match[1]))
        .filter((value) => Number.isFinite(value));
      if (keys.length === 1 ? numbers.length < 1 : numbers.length < keys.length) continue;
      for (let item = 0; item < keys.length; item += 1) {
        const key = keys[item];
        const value = numbers[item];
        if (key !== undefined && key.length > 0 && value !== undefined && output.has(key) === false) {
          output.set(key, value);
        }
      }
      break;
    }
  }
  return output;
}

function parseNpcStatsText(raw) {
  const text = normalizeText(raw);
  const attributePairs = collectDirectMatches(text, ATTRIBUTE_GROUPS, false);
  const alignedPairs = extractAlignedPairs(text);

  const attributes = {};
  for (const group of ATTRIBUTE_GROUPS) {
    const value = attributePairs.get(group.key) ?? alignedPairs.get(group.key);
    if (value !== undefined && Number.isFinite(value) && value >= 0 && value <= 999) {
      attributes[group.key] = Math.floor(value);
    }
  }

  const vitalPairs = collectDirectMatches(text, VITAL_GROUPS, true);
  const vitalLimits = {
    hp: { min: 1, max: 9999 },
    mp: { min: 0, max: 99999 },
    san: { min: 0, max: 999 },
    dp: { min: 0, max: 99999 }
  };
  const vitalValues = {};
  for (const group of VITAL_GROUPS) {
    const value = vitalPairs.get(group.key);
    const limit = vitalLimits[group.key];
    if (value !== undefined && Number.isFinite(value) && value >= limit.min && value <= limit.max) {
      vitalValues[group.key] = Math.floor(value);
    }
  }

  return {
    attributes,
    maxHp: vitalValues.hp ?? null,
    maxMp: vitalValues.mp ?? null,
    maxSan: vitalValues.san ?? null,
    maxDp: vitalValues.dp ?? null,
    matchedAttributes: Object.keys(attributes).length,
    matchedVitals: Object.keys(vitalValues).length
  };
}

function scoreOf(parsed) {
  return (parsed.matchedAttributes || 0) * 10 + (parsed.matchedVitals || 0) * 4;
}

function isUsable(parsed) {
  return scoreOf(parsed) >= 30;
}

function recordOf(value) {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return {};
  return value;
}

function stringOf(value) {
  return typeof value === "string" ? value.trim() : "";
}

function stringListOf(value) {
  if (typeof value === "string" && value.trim().length > 0) return [value.trim()];
  if (Array.isArray(value)) {
    return value
      .filter((item) => typeof item === "string" && item.trim().length > 0)
      .map((item) => item.trim());
  }
  return [];
}

function candidateNamesOf(entry) {
  const names = new Set();
  for (const field of ["name", "fullName", "realName", "trueName", "commonName", "nickname", "aliases", "alias", "aka", "alsoKnownAs"]) {
    for (const name of stringListOf(entry[field])) names.add(name);
  }
  if (names.size === 0) {
    const fallback = stringOf(entry.title) || stringOf(entry.id);
    if (fallback.length > 0) names.add(fallback);
  }
  return [...names].filter((name) => name.length >= 2).slice(0, 12);
}

function nameVariants(name) {
  const base = String(name || "").trim();
  const variants = new Set();
  if (base.length >= 2) variants.add(base);
  for (const separator of ["（", "(", "：", ":", " - ", "—", "【"]) {
    const index = base.indexOf(separator);
    if (index >= 2) variants.add(base.slice(0, index).trim());
  }
  return [...variants].filter((item) => item.length >= 2).slice(0, 6);
}

function bestStatsNearName(sourceText, name) {
  const source = String(sourceText || "");
  const lower = source.toLowerCase();
  let best = null;
  let bestScore = -1;

  for (const variant of nameVariants(name)) {
    const needle = variant.toLowerCase();
    let from = 0;
    let hits = 0;
    while (hits < 8) {
      const index = lower.indexOf(needle, from);
      if (index < 0) break;
      hits += 1;
      const after = source.slice(index, Math.min(source.length, index + 2600));
      if (after.trim().length > 0) {
        const parsed = parseNpcStatsText(after);
        const score = scoreOf(parsed);
        if (score > bestScore) {
          best = parsed;
          bestScore = score;
        }
      }
      from = index + Math.max(1, needle.length);
    }
  }

  if (bestScore < 30) {
    for (const variant of nameVariants(name)) {
      const needle = variant.toLowerCase();
      let from = 0;
      let hits = 0;
      while (hits < 8) {
        const index = lower.indexOf(needle, from);
        if (index < 0) break;
        hits += 1;
        const before = source.slice(Math.max(0, index - 2600), Math.min(source.length, index + 120));
        const parsed = parseNpcStatsText(before);
        const score = scoreOf(parsed);
        if (score > bestScore) {
          best = parsed;
          bestScore = score;
        }
        from = index + Math.max(1, needle.length);
      }
    }
  }

  return bestScore >= 30 ? best : null;
}

function mergeStats(entry, parsed) {
  const attributes = { ...recordOf(entry.attributes) };
  for (const key of NPC_STAT_ATTRIBUTE_KEYS) {
    const value = parsed.attributes[key];
    if (value !== undefined) attributes[key] = value;
  }
  if (Object.keys(attributes).length > 0) entry.attributes = attributes;
  if (parsed.maxHp !== null) entry.maxHp = parsed.maxHp;
  if (parsed.maxMp !== null) entry.maxMp = parsed.maxMp;
  if (parsed.maxSan !== null) entry.maxSan = parsed.maxSan;
  if (parsed.maxDp !== null) entry.maxDp = parsed.maxDp;
}

function enrichNpcStatsFromSources(entries, sources) {
  let enriched = 0;
  for (const entry of entries) {
    let best = null;
    let bestScore = -1;
    for (const field of ["statText", "attributesText", "statsText", "attributeText", "statLine", "attributes"]) {
      const raw = entry[field];
      if (typeof raw !== "string" || raw.trim().length === 0) continue;
      const parsed = parseNpcStatsText(raw);
      const score = scoreOf(parsed);
      if (score > bestScore) {
        best = parsed;
        bestScore = score;
      }
    }

    for (const name of candidateNamesOf(entry)) {
      for (const source of sources) {
        const parsed = bestStatsNearName(source.text, name);
        if (parsed === null) continue;
        const score = scoreOf(parsed);
        if (score > bestScore) {
          best = parsed;
          bestScore = score;
        }
      }
    }

    if (best === null || isUsable(best) === false) continue;
    mergeStats(entry, best);
    enriched += 1;
  }
  return enriched;
}

function parsedFromEntry(entry) {
  const attrs = recordOf(entry.attributes);
  const attributes = {};
  for (const key of NPC_STAT_ATTRIBUTE_KEYS) {
    const upper = key.toUpperCase();
    const raw = attrs[key] ?? attrs[upper];
    const value = Number(raw);
    if (Number.isFinite(value) && value >= 0 && value <= 999) attributes[key] = Math.floor(value);
  }
  const vital = (name) => {
    const value = Number(entry[name]);
    return Number.isFinite(value) ? Math.floor(value) : null;
  };
  const parsed = {
    attributes,
    maxHp: vital("maxHp"),
    maxMp: vital("maxMp"),
    maxSan: vital("maxSan"),
    maxDp: vital("maxDp"),
    matchedAttributes: Object.keys(attributes).length,
    matchedVitals: 0
  };
  if (parsed.maxHp !== null) parsed.matchedVitals += 1;
  if (parsed.maxMp !== null) parsed.matchedVitals += 1;
  if (parsed.maxSan !== null) parsed.matchedVitals += 1;
  if (parsed.maxDp !== null) parsed.matchedVitals += 1;
  return parsed;
}

function isLikelyNpcHeading(raw) {
  let line = String(raw || "").trim();
  if (line.length === 0) return "";
  line = line.replace(/^#{1,6}\s+/, "").trim();
  line = line.replace(/^【|】$/g, "").trim();
  line = line.replace(/^[>*\-•·]+\s*/, "").trim();
  if (line.length < 2 || line.length > 48) return "";
  if (/^[\d\s.,，、;；:：+\-]+$/.test(line)) return "";
  if (containsValueAfterLabel(line, ALL_GROUPS)) return "";
  if (labelsInOrder(line, ALL_GROUPS).length > 0) return "";
  if (/[。！？!?；;]$/.test(line)) return "";
  if (/^(属性|数值|数据|能力|技能|装备|物品|道具|描述|说明|备注|注|来源|页码|第[一二三四五六七八九十百0-9]+[章节条项幕])/.test(line)) return "";
  if (line.includes(":") || line.includes("：")) {
    const prefix = line.split(/[:：]/)[0].trim();
    if (prefix.length >= 2 && prefix.length <= 24 && /[\u4e00-\u9fa5A-Za-z]/.test(prefix)) return prefix;
    return "";
  }
  return line;
}

function harvestStatBlocks(sources) {
  const output = [];
  for (const source of sources) {
    const text = normalizeText(source && source.text);
    const lines = text.split("\n").map((line) => line.trim());
    for (let index = 0; index < lines.length; index += 1) {
      const line = lines[index] || "";
      if (line.length === 0) continue;
      const inline = containsValueAfterLabel(line, ALL_GROUPS);
      const labels = labelsInOrder(line, ALL_GROUPS);
      if (!inline && labels.length < 2) continue;

      const from = inline ? Math.max(0, index - 1) : index;
      const to = inline ? Math.min(lines.length, index + 2) : Math.min(lines.length, index + 3);
      const parsed = parseNpcStatsText(lines.slice(from, to).join("\n"));
      if (isUsable(parsed) === false) continue;

      let name = "";
      for (let cursor = index - 1; cursor >= Math.max(0, index - 8); cursor -= 1) {
        const candidate = isLikelyNpcHeading(lines[cursor]);
        if (candidate.length > 0) {
          name = candidate;
          break;
        }
        const previousLabels = labelsInOrder(lines[cursor], ALL_GROUPS);
        if (previousLabels.length > 0) continue;
        if (/^[\d\s.,，、;；:：+\-]+$/.test(lines[cursor])) continue;
      }
      if (name.length === 0) continue;
      output.push({
        name,
        sourceFilename: source.filename || "",
        attributes: parsed.attributes,
        maxHp: parsed.maxHp,
        maxMp: parsed.maxMp,
        maxSan: parsed.maxSan,
        maxDp: parsed.maxDp,
        matchedAttributes: parsed.matchedAttributes,
        matchedVitals: parsed.matchedVitals
      });
    }
  }
  return output;
}

function buildNpcStats(input) {
  const entries = Array.isArray(input && input.entries) ? input.entries : [];
  const sources = Array.isArray(input && input.sources) ? input.sources : [];
  const byKey = new Map();

  function addRecord(name, parsed, sourceName) {
    const key = normalizeNameKey(name);
    if (key.length < 2 || parsed === null) return;
    let target = byKey.get(key);
    if (target === undefined) {
      target = {
        name,
        aliases: [],
        source: sourceName || "",
        attributes: {},
        maxHp: null,
        maxMp: null,
        maxSan: null,
        maxDp: null
      };
      byKey.set(key, target);
    }
    if (sourceName && target.source.length === 0) target.source = sourceName;
    for (const attr of NPC_STAT_ATTRIBUTE_KEYS) {
      const value = parsed.attributes[attr];
      if (value !== undefined && value !== null) target.attributes[attr] = value;
    }
    if (parsed.maxHp !== null && parsed.maxHp !== undefined) target.maxHp = parsed.maxHp;
    if (parsed.maxMp !== null && parsed.maxMp !== undefined) target.maxMp = parsed.maxMp;
    if (parsed.maxSan !== null && parsed.maxSan !== undefined) target.maxSan = parsed.maxSan;
    if (parsed.maxDp !== null && parsed.maxDp !== undefined) target.maxDp = parsed.maxDp;
  }

  const aiEntries = entries.map((entry) => ({ ...recordOf(entry), attributes: { ...recordOf(entry.attributes) } }));
  if (sources.length > 0) enrichNpcStatsFromSources(aiEntries, sources);
  for (const entry of aiEntries) {
    const names = candidateNamesOf(entry);
    if (names.length === 0) continue;
    const parsed = parsedFromEntry(entry);
    if (isUsable(parsed) === false) continue;
    addRecord(names[0], parsed, entry.id || "");
    const target = byKey.get(normalizeNameKey(names[0]));
    if (target !== undefined) {
      for (const alias of names.slice(1)) {
        if (target.aliases.includes(alias) === false) target.aliases.push(alias);
      }
    }
  }

  for (const block of harvestStatBlocks(sources)) {
    addRecord(block.name, block, block.sourceFilename || "");
    const target = byKey.get(normalizeNameKey(block.name));
    if (target !== undefined && target.aliases.length === 0) target.aliases = nameVariants(block.name).slice(1);
  }

  return [...byKey.values()].map((item) => ({
    name: item.name,
    aliases: item.aliases,
    source: item.source,
    attributes: item.attributes,
    maxHp: item.maxHp,
    maxMp: item.maxMp,
    maxSan: item.maxSan,
    maxDp: item.maxDp
  }));
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = {
    NPC_STAT_ATTRIBUTE_KEYS,
    ATTRIBUTE_GROUPS,
    VITAL_GROUPS,
    normalizeText,
    normalizeNameKey,
    parseNpcStatsText,
    scoreOf,
    isUsable,
    candidateNamesOf,
    bestStatsNearName,
    enrichNpcStatsFromSources,
    harvestStatBlocks,
    buildNpcStats
  };
}


const rawRoot = $("Webhook 团本解析").first().json;
const root = (rawRoot && rawRoot.body && typeof rawRoot.body === "object") ? rawRoot.body : rawRoot;
const sources = Array.isArray(root.sources) ? root.sources : [];
const images = Array.isArray(root.images) ? root.images : [];
const requestItems = $("按场景分块").all().map((item) => (item && item.json) ? item.json : {});
const chunkRequestCount = requestItems.filter((item) => item.kind !== "image").length;

const SECTION_SET = new Set([
  "元信息", "真相与背景", "剧情梗概", "开场钩子", "关键NPC", "地点与场景", "线索", "遭遇与战斗", "道具与手书", "怪物与神话生物", "结局分支", "奖励与成长", "KP备注", "附录"
]);

function asRecord(value) {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return {};
  return value;
}

function asString(value, fallback) {
  if (typeof value === "string") return value.trim();
  if (typeof value === "number") return String(value);
  return fallback === undefined ? "" : fallback;
}

function asObjectArray(value) {
  if (Array.isArray(value)) return value.map(asRecord);
  if (value !== null && typeof value === "object") return [asRecord(value)];
  return [];
}

function repairJsonText(text) {
  let output = "";
  let inString = false;
  let escaped = false;
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];
    if (inString) {
      if (escaped) {
        output += char;
        escaped = false;
        continue;
      }
      if (char === "\\") {
        output += char;
        escaped = true;
        continue;
      }
      if (char === '"') {
        output += char;
        inString = false;
        continue;
      }
      if (char === "\n") {
        output += "\\n";
        continue;
      }
      if (char === "\r") {
        output += "\\r";
        continue;
      }
      if (char === "\t") {
        output += "\\t";
        continue;
      }
      output += char;
      continue;
    }
    if (char === '"') {
      inString = true;
      output += char;
      continue;
    }
    output += char;
  }
  // 去掉对象 / 数组结尾前多余的逗号
  return output.replace(/,\s*([}\]])/g, "$1");
}

function extractJsonObject(text) {
  const trimmed = String(text || "").trim();
  const withoutFence = trimmed
    .replace(/^```(?:json)?\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  const candidates = [];
  candidates.push(withoutFence);
  const start = withoutFence.indexOf("{");
  const end = withoutFence.lastIndexOf("}");
  if (start >= 0 && end > start) candidates.push(withoutFence.slice(start, end + 1));

  let lastError = null;
  for (const candidate of candidates) {
    try {
      return JSON.parse(candidate);
    } catch (error) {
      lastError = error;
    }
    const repaired = repairJsonText(candidate);
    if (repaired !== candidate) {
      try {
        return JSON.parse(repaired);
      } catch (error) {
        lastError = error;
      }
    }
  }
  const prefix = withoutFence.slice(0, 500);
  throw new Error("模型返回 JSON 无法解析：" + (lastError instanceof Error ? lastError.message : String(lastError)) + "；内容开头：" + prefix);
}

function normalizeChunkExtraction(raw, label) {
  const rootNode = asRecord(raw);
  const metaRaw = asRecord(rootNode.meta ?? rootNode.frontMatter ?? {});
  const meta = {};
  for (const key of ["title", "summary", "background", "occupationRecommendation"]) {
    const value = asString(metaRaw[key]);
    if (value.length > 0) meta[key] = value;
  }
  const sectionsRaw = asRecord(rootNode.sections ?? rootNode["章节"] ?? {});
  const sections = {};
  for (const section of SECTION_SET) {
    const value = asString(sectionsRaw[section] ?? sectionsRaw[section.replace(/与/g, "")] ?? "");
    if (value.length > 0) sections[section] = value;
  }
  const structuredRaw = asRecord(rootNode.structured ?? rootNode["结构化数据"] ?? {});
  const structured = {};
  const pluralMap = {
    chapters: "chapter", scenes: "scene", encounters: "encounter", npcs: "npc",
    clues: "clue", items: "item", endings: "ending", rewards: "reward", magic: "magic", spells: "magic"
  };
  for (const [rawKind, value] of Object.entries(structuredRaw)) {
    const plural = rawKind === "spells" ? "magic" : rawKind;
    const kind = pluralMap[plural] || pluralMap[plural.replace(/s$/, "")];
    if (kind === undefined) continue;
    const entries = asObjectArray(value);
    if (entries.length > 0) structured[kind] = entries;
  }
  return { label, meta, sections, structured };
}

function normalizeImageExtractions(raw, batch) {
  const records = asObjectArray(asRecord(raw).images);
  const results = [];
  for (let index = 0; index < batch.length; index += 1) {
    const image = batch[index];
    const record = records.find((item) => asString(item.filename) === image.filename) || records[index] || {};
    const kindRaw = asString(record.kind).toUpperCase();
    const kinds = ["MAP", "SCENE", "HANDOUT", "CLUE", "NPC", "ITEM", "TEXT", "OTHER"];
    const kind = kinds.includes(kindRaw) ? kindRaw : "OTHER";
    const rawSection = asString(record.section);
    const section = SECTION_SET.has(rawSection) ? rawSection : "附录";
    results.push({
      filename: image.filename,
      relativePath: image.relativePath,
      kind,
      transcription: asString(record.transcription).slice(0, 4000),
      description: asString(record.description).slice(0, 3000),
      section,
      sectionText: asString(record.sectionText).slice(0, 3000),
      scene: record.scene && typeof record.scene === "object" && !Array.isArray(record.scene) ? record.scene : null,
      clue: record.clue && typeof record.clue === "object" && !Array.isArray(record.clue) ? record.clue : null,
      npc: record.npc && typeof record.npc === "object" && !Array.isArray(record.npc) ? record.npc : null,
      item: record.item && typeof record.item === "object" && !Array.isArray(record.item) ? record.item : null
    });
  }
  return results;
}

const extractions = [];
const imageExtractions = [];
const warnings = [];
let aiCalls = 0;

for (let index = 0; index < items.length; index += 1) {
  const response = items[index] && items[index].json ? items[index].json : {};
  const request = requestItems[index] || {};
  const isImage = request.kind === "image";
  const label = String(request.label || (isImage ? "图片分析" : "文本场景段"));
  const batch = Array.isArray(request.imageBatch) ? request.imageBatch : [];
  const choice = Array.isArray(response.choices) ? response.choices[0] : null;
  const finishReason = choice ? choice.finish_reason : "";
  const content = choice && choice.message ? choice.message.content : "";

  if (finishReason === "length") {
    throw new Error(label + " 触发 max_tokens 截断；请拆分素材后重试");
  }
  if (typeof content !== "string" || content.trim().length === 0) {
    warnings.push("模型第 " + String(index + 1) + " 次调用没有返回正文，已跳过");
    continue;
  }

  aiCalls += 1;
  if (isImage) {
    if (batch.length > 0) imageExtractions.push(...normalizeImageExtractions(extractJsonObject(content), batch));
  } else {
    extractions.push(normalizeChunkExtraction(extractJsonObject(content), label));
  }
}

const npcEntries = [];
for (const extraction of extractions) {
  const npcs = extraction && extraction.structured ? extraction.structured.npcs : null;
  if (Array.isArray(npcs)) for (const entry of npcs) npcEntries.push(entry);
}
const npcStats = buildNpcStats({ entries: npcEntries, sources });

return [{
  json: {
    ok: true,
    extractions,
    images: imageExtractions,
    npcStats,
    warnings,
    stats: {
      aiCalls,
      attempts: 1,
      chunks: chunkRequestCount,
      chunksCompleted: extractions.length,
      imagesAnalyzed: imageExtractions.length,
      imagesUsed: images.length,
      npcStatsParsed: npcStats.length
    }
  }
}];
